  if(a==='jname'){const v=($('j-name').value||'').trim().replace(/[<>&"{}]/g,'').slice(0,14);if(!v){$('j-name').focus();return true;}meSt().name=v.charAt(0).toUpperCase()+v.slice(1);save();sfx('shimmer');renderStory();return true;}
