    +'<div class="btns acts"><button class="btn" data-act="speak"'+(v.ok?'':' disabled')+'>Speak</button>'+(S.cfg.ramp&&!S.puz&&ui.adjs.length===1&&!ui.subj&&ui.verb==null&&!ui.kverb&&ui.clime==null&&!S.players[0].veil?'<button class="btn ghost" data-act="veil" title="Lay this adjective face down. It springs on the first thing of the rival’s that turns on you.">Lay it face down</button>':'')+'<button class="btn ghost" data-act="clear">Clear</button>'+(S.puz&&(sNode(S.puz).puz.turns||1)>1?'<button class="btn ghost" data-act="pwait"'+(S.left>1?'':' disabled')+'>'+(S.left>1?'Let a turn pass<br><small>'+(S.left-1)+' left</small>':'No turns left')+'</button>':'')+'<button class="btn wax" data-act="end">'+(S.puz?'Start again':ui.endWarn?'End anyway':'End turn')+'</button></div>';
