function rxClue(x){const fam=w=>{const d=W[w];if(!d)return'something';const p=d.props||[];if(p.includes('ground'))return w;if(d.t===CLIME)return'a weather';return p.includes('metal')?'a metal':p.includes('beast')?'a beast':p.includes('plant')?'a plant':p.includes('liquid')?'a liquid':p.includes('stone')?'a stone':p.includes('spirit')?'a spirit':'a thing';};
  const r=x.r&&W[x.r];let what='Something';if(r){const p=r.props||[];what=r.t===CLIME?'A weather':p.includes('ground')?'A new element':p.includes('metal')?'A metal':p.includes('beast')?'A creature':p.includes('plant')?'A growing thing':p.includes('liquid')?'A liquid':'A thing';
    const how=p.includes('flying')||p.includes('bird')?', that flies':p.includes('fireborn')?', born of fire':p.includes('toxic')?', that poisons':p.includes('sacred')?', that is holy':p.includes('heavy')?', that is heavy':'';what+=how;}
  else what=x.fx==='heal'?'A healing':x.fx==='blast'||x.fx==='firestorm'?'A burst of fire':x.fx==='inkburst'?'A rush of breath':'A working';
  return what+', from '+fam(x.a)+' and '+fam(x.b)+'.';}
