(()=>{let svg=null,path=null,head=null,raf=0,last=null;
  function mk(){svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.id='tarrow';svg.setAttribute('aria-hidden','true');
    svg.innerHTML='<defs><filter id="tglow" x="-50%" y="-50%" width="200%" height="200%"><feGaussianBlur stdDeviation="4" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter><linearGradient id="tgrad" x1="0" x2="1"><stop offset="0" stop-color="#8fd0ff" stop-opacity=".15"/><stop offset="1" stop-color="#d9f1ff"/></linearGradient></defs><path class="ta" fill="none" stroke="url(#tgrad)" stroke-width="7" stroke-linecap="round" stroke-dasharray="2 14" filter="url(#tglow)"/><path class="tb" fill="none" stroke="#8fd0ff" stroke-width="2.5" stroke-linecap="round" filter="url(#tglow)"/><polygon class="th" fill="#e3f5ff" filter="url(#tglow)"/>';
    document.body.appendChild(svg);path=svg.querySelectorAll('path');head=svg.querySelector('polygon');}
  function hide(){if(svg)svg.style.display='none';}
  function draw(e){raf=0;if(typeof S==='undefined'||!S||view!=='match'||S.phase!=='play'||!ui.subj||ui.subj.k!=='thing'||RM){hide();return;}
    const src=elThing(ui.subj.id);if(!src){hide();return;}if(!svg)mk();
    const r=src.getBoundingClientRect(),x0=r.left+r.width/2,y0=r.top+r.height*.3;let x1=e.clientX,y1=e.clientY;
    const tg=e.target&&e.target.closest&&e.target.closest('#rival .thing,#rivalhead .who,#you .thing,#youhead .who');
    if(tg&&tg!==src){const q=tg.getBoundingClientRect();x1=q.left+q.width/2;y1=q.top+q.height/2;svg.classList.add('lock');}else svg.classList.remove('lock');
    if(Math.hypot(x1-x0,y1-y0)<40){hide();return;}
    const mx=(x0+x1)/2,my=Math.min(y0,y1)-Math.max(60,Math.abs(x1-x0)*.25),d='M'+x0+' '+y0+' Q'+mx+' '+my+' '+x1+' '+y1;
    path.forEach(p=>p.setAttribute('d',d));const ang=Math.atan2(y1-my,x1-mx),L=22,W=12;
    head.setAttribute('points',[[x1,y1],[x1-L*Math.cos(ang)+W*Math.sin(ang),y1-L*Math.sin(ang)-W*Math.cos(ang)],[x1-L*Math.cos(ang)-W*Math.sin(ang),y1-L*Math.sin(ang)+W*Math.cos(ang)]].map(p=>p.join(',')).join(' '));
    svg.style.display='block';}
  addEventListener('pointermove',e=>{last=e;if(!raf)raf=requestAnimationFrame(()=>draw(last));},{passive:true});
  addEventListener('pointerdown',()=>setTimeout(()=>{if(last)draw(last);},30),{passive:true});
  addEventListener('keydown',e=>{if(e.key==='Escape')hide();});setInterval(()=>{if(svg&&svg.style.display!=='none'&&(typeof ui==='undefined'||!ui.subj||ui.subj.k!=='thing'||!S||S.phase!=='play'))hide();},120);})();
/* ===== hover zoom: the full card beside a thing on the table ===== */
(()=>{let tm=0,box=null,cur=null;
  function hide(){clearTimeout(tm);cur=null;if(box)box.classList.remove('on');}
  addEventListener('pointerover',e=>{const el=e.target.closest&&e.target.closest('#rival .thing,#you .thing');if(!el||el===cur)return;if(typeof S==='undefined'||!S||view!=='match'||el.classList.contains('hidden'))return;
    hide();cur=el;tm=setTimeout(()=>{const id=+el.dataset.id,t=S.things.find(x=>x.id===id);if(!t||!W[t.w])return;if(!box){box=document.createElement('div');box.id='zoomc';document.body.appendChild(box);}
      const r=el.getBoundingClientRect(),right=r.right+260<innerWidth;
      box.innerHTML='<div class="card '+W[t.w].t+' static">'+fullFace(t.w,{lv:upOf(S,t.side,t.w)})+'</div>'+(t.verbs&&t.verbs.length?'<p class="zk">Knows '+esc(t.verbs.join(', '))+'</p>':'');
      box.style.left=(right?r.right+14:r.left-14-230)+'px';box.style.top=Math.max(10,Math.min(innerHeight-360,r.top-60))+'px';box.classList.add('on');},420);},{passive:true});
  addEventListener('pointerout',e=>{const el=e.target.closest&&e.target.closest('#rival .thing,#you .thing');if(el&&!el.contains(e.relatedTarget))hide();},{passive:true});
  addEventListener('pointerdown',hide,{passive:true});})();
